import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第四十五卦 萃 澤地萃 兌上坤下","description":"周易 - 第四十五卦 萃 澤地萃 兌上坤下","frontmatter":{"title":"第四十五卦 萃 澤地萃 兌上坤下","description":"周易 - 第四十五卦 萃 澤地萃 兌上坤下"},"headers":[],"relativePath":"classics/zhouyi/046.md","filePath":"classics/zhouyi/046.md"}'),l={name:"classics/zhouyi/046.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="萃" tabindex="-1">萃 <a class="header-anchor" href="#萃" aria-label="Permalink to “萃”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨。王假有廟，利見大人，亨，利貞。用大牲吉，利有攸往。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>萃，聚也；順以說，剛中而應，故聚也。王假有廟，致孝享也。利見大人亨，聚以正也。用大牲吉，利有攸往，順天命也。觀其所聚，而天地萬物之情可見矣。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>澤上於地，萃；君子以除戎器，戒不虞。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>有孚不終，乃亂乃萃，若號一握 為笑，勿恤，往無咎。象曰：乃亂乃萃，其志亂也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>引吉，無咎，孚乃利用禴。象曰：引吉無咎，中未變也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>萃如，嗟如，無攸利，往無咎，小吝。象曰：往無咎，上巽也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>大吉，無咎。象曰：大吉無咎，位不當也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>萃有位，無咎。匪孚，元永貞，悔亡。象曰：萃有位，志未光也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>齎諮涕洟，無咎。象曰：齎諮涕洟，未安上也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
